"""Generate Step 3 counts, examples, assumptions and stop point in README.md."""
from pathlib import Path
import json,time,datetime,importlib.util,sys,re
import pandas as pd
import pyarrow.parquet as pq
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'data';S=ROOT/'scripts'
spec=importlib.util.spec_from_file_location('report_losses',S/'report_losses.py');m=importlib.util.module_from_spec(spec);sys.modules['report_losses']=m;spec.loader.exec_module(m);md=m.md

def read(name):return json.loads((D/name).read_text())
def main():
    started=time.time();build=read('step3_build_status.json');v=read('step3_validation.json');nv=read('step3_neighbor_validation.json');assert v['all_passed'] and nv['all_passed'];sc=read('retrieval_scaler.json');examples=read('retrieval_examples.json');diag=read('loss_diagnostics_status.json')
    cols=['split','year','market_name','cohort_flag','ts','outcome_observed_24h','liquidated_within_24h','index_eligible','binance_fallback','active_borrow','dust_collateral_under_004_usd','in_validated_replay_episode','feature_complete','feed_stale','missing_position_hour','label_window_missing_24h']
    frames=[];dust=[];extra={'inactive_or_zero_balance_hours':0,'outside_validated_episode_hours':0,'known_stale_hours':0,'unknown_label_missing_window_hours':0}
    for batch in pq.ParquetFile(D/'retrieval.parquet').iter_batches(batch_size=200000,columns=cols):
        f=batch.to_pandas();f['positive_flag']=f.liquidated_within_24h.fillna(False).astype('int64');frames.append(f.groupby(['split','year','market_name','cohort_flag']).agg(hours=('ts','size'),known_labels=('outcome_observed_24h','sum'),positive_24h=('positive_flag','sum'),index_eligible=('index_eligible','sum'),fallback_hours=('binance_fallback','sum')).reset_index());dust.append(f.groupby(['split','dust_collateral_under_004_usd']).agg(hours=('ts','size'),known_labels=('outcome_observed_24h','sum'),positive_24h=('positive_flag','sum')).reset_index())
        extra['inactive_or_zero_balance_hours']+=int((~f.active_borrow).sum());extra['outside_validated_episode_hours']+=int((~f.in_validated_replay_episode).sum());extra['known_stale_hours']+=int(f.feed_stale.fillna(False).sum());extra['unknown_label_missing_window_hours']+=int((~f.outcome_observed_24h & f.label_window_missing_24h).sum())
    counts=pd.concat(frames).groupby(['split','year','market_name','cohort_flag']).sum(numeric_only=True).reset_index();counts.to_csv(D/'retrieval_counts.csv',index=False);dust=pd.concat(dust).groupby(['split','dust_collateral_under_004_usd']).sum(numeric_only=True).reset_index();dust.to_csv(D/'retrieval_dust_counts.csv',index=False)
    assert counts.hours.sum()==build['screen_hours'];assert counts.positive_24h.sum()==build['positive_24h'];assert counts.known_labels.sum()==build['positive_24h']+build['negative_24h']
    timing=[dict(task='DEFAULT loss diagnostics',seconds=diag['elapsed_s']),dict(task='Loss report',seconds=read('loss_report_status.json')['elapsed_s']),dict(task='Retrieval table build',seconds=build['elapsed_s']),dict(task='Five examples, including selection',seconds=examples['total_example_elapsed_s']),dict(task='Whole-table and source validation',seconds=v['elapsed_s']),dict(task='Full-sort neighbor and CLI validation',seconds=nv['elapsed_s'])]
    if (D/'step3_summary_migration.json').exists():timing.append(dict(task='Summary readability migration',seconds=read('step3_summary_migration.json')['elapsed_s']))
    wall=time.time()-diag['started_at'];metrics=[('Input feature hours',build['input_hours']),('Reconstruction-failure positions excluded',build['excluded_failed_positions']),('Hours excluded with those positions',build['excluded_reconstruction_hours']),('Screen-triggered hours retained',build['screen_hours']),('Unique retained positions',build['positions']),('Known positive 24h outcomes',build['positive_24h']),('Known negative 24h outcomes',build['negative_24h']),('Unknown/masked 24h outcomes',build['unknown_label_hours']),('Retained hours with missing position state',build['missing_state_screen_hours']),('Incomplete feature vectors',build['feature_incomplete_hours']),('Rows eligible for nearest-neighbor search',build['index_eligible_hours']),('Mature pre-2026 scaler/candidate rows',build['scaler_training_rows']),('Binance-fallback flag at the hour',build['binance_fallback_hours']),('Hours in a replay episode containing fallback',build['episode_binance_fallback_hours']),('Small Ethereum cohort hours',build['small_cohort_hours']),('Feed-staleness unknown/partly unknown',build['staleness_unknown_hours'])]
    text=['## Step 3 — retrieval completed',
    'The default corridor is retained: act 70%, target 50%, daily sell budget 20%, maximum slice 25%, cooldown 120 seconds and execution delay 120 seconds. `data/retrieval.parquet` contains one row per position/hour whenever any specified screen fires. Its outcomes are **observed Morpho events and owner actions**, not the counterfactual DEFAULT replay. Aave remains excluded. No Step 4 model or Step 5 judge call has been run.',
    '### Counts and scope',
    'Rows: `data/retrieval.parquet`, built from `data/features_hourly.parquet`; totals in `data/step3_build_status.json`. Flags overlap and must not be added together.',md(pd.DataFrame(metrics,columns=['measure','count'])),
    f"The parquet file is {build['bytes']:,} bytes ({build['bytes']/1024**2:.2f} MiB). Of the retained rows, {extra['inactive_or_zero_balance_hours']:,} have no active positive-collateral/positive-debt balance. They are retained because a market-wide screen can fire even for an inactive position; `active_borrow` makes this explicit. {extra['outside_validated_episode_hours']:,} lie outside eligible six-day replay windows. Retrieval uses the full pulled hourly context, with `in_validated_replay_episode` distinguishing the overlap.",
    '[ASSUMPTION] Excluding the 13 failed reconstructions means excluding **all hours of their 13 market/borrower positions**, not just the failed six-day intervals. This conservatively removes 8,568 source hours. Exact keys and windows are in `data/retrieval_reconstruction_exclusions.csv`. The small Ethereum cohorts remain: `cohort_flag` distinguishes Ethereum WETH (holdout-only) and wstETH (the unchanged 483-survivor census). No new survivor sampling was done.',
    'Market/year counts below come from `data/retrieval_counts.csv`; positive outcomes count position-hours, so multiple hours may precede the same liquidation. `known_labels` excludes missing/censored windows; `index_eligible` additionally requires a complete feature vector and observed current state.',md(counts.drop(columns=['cohort_flag'])),
    '### Screens, flags and no imputation',
    'Overlapping screen counts from `data/retrieval_screen_counts.csv`:',md(pd.read_csv(D/'retrieval_screen_counts.csv')),
    'Screens are exactly LTV > 0.70, oracle/Binance percentage gap > 2 (a positive gap, not its absolute value), utilization > 0.95, or a known stale feed. Their four boolean columns identify why a row entered. The full Step 2 feature vector is preserved without replacing missing values. Missing rows can enter through market-wide utilization or staleness; their missing-state and label-window booleans remain visible and they cannot enter the nearest-neighbor candidate pool.',
    '[ASSUMPTION] Staleness uses the last usable round as of the hour and the phase-boundary rules from Step 1. Operational thresholds are 1,200 seconds for Base BTC/ETH price feeds, 3,600 seconds for Ethereum ETH and USDC/ETH feeds, and 86,400 seconds for the Base USDC/USD quote feed and the fetched wstETH exchange-rate observation. These are declared research thresholds, not newly verified feed heartbeat configurations. `data/retrieval_feed_thresholds.json` records every component. An unresolved phase yields unknown component age, not fresh age; unknown alone does not trigger the stale screen. A known stale component can still trigger it when another component is unknown.',
    '`binance_fallback` means the replay oracle reconstruction would require Binance at that hour; `episode_binance_fallback` means the hour lies in an eligible replay episode containing any fallback span. Both are retained and displayed in summaries. The original hourly Morpho `oracle_px` and its feature gap remain unchanged; these flags do not replace that observed feature with Binance. `feed_staleness_unknown` identifies incomplete age evidence.',
    '[ASSUMPTION] The accepted stETH/ETH parity treatment is preserved. Morpho’s wstETH oracles price through the exchange rate, so parity matches the venue convention used in this reconstruction; wstETH/Binance comparisons use the fetched exchange rate as of the hour.',
    '### Observed outcomes and summaries',
    'The outcome window is `(hour, hour + 24h]`. `liquidated_within_24h`, liquidation-event count, collateral seized, debt repaid, penalty estimate and owner-action counts all use cached observed transactions. `hours_to_liquidation` is the lead to the first liquidation **within that 24-hour window**; it is null for negatives and unknown windows. Later events are not exposed by an outcome that has only matured for 24 hours. Owner actions count SupplyCollateral, WithdrawCollateral, Borrow and Repay separately, with a readable action string. Events timestamped exactly at the hour belong to prior/current state, not the future window.',
    '[ASSUMPTION] `penalty_paid_24h_usd` is the contractual liquidation-incentive estimate: sum of actual repaid USDC × `[1 / (0.3 × LLTV + 0.7) − 1]`. USDC is treated as USD, as in Step 2. It is not a separately observed fee transfer or a Binance-marked realized loss; it excludes bad debt and gas. `collateral_seized_24h` is the actual token quantity. The summary’s seized percentage divides this quantity by collateral at the query hour, so later owner deposits can make it exceed 100%. Unknown label windows have null outcome fields, never imputed zeros.',
    'Every row has a readable `summary`, the complete feature vector, the four screen flags, source/cohort/state flags, and observed outcomes. Case-level replay diagnostics stay in separate tables so the judge cannot confuse simulated saves with historical events.',
    '### Retrieval method and interface',
    f"`scripts/retrieve.py` returns the exact k nearest rows by standardized Euclidean distance. The frozen scaler uses {sc['training_rows']:,} complete, labeled hours whose full 24-hour outcomes matured strictly before 1 January 2026, across {sc['training_positions']:,} positions. The default candidate pool is the same mature pre-2026 library. A query excludes its own market/borrower position when supplied via `--row-id`. Candidates must also have matured by `--as-of`. The optional `--pool past` explicitly permits mature holdout rows; none of the five examples uses that option.",
    '[ASSUMPTION] All eleven Step 2 numeric features receive equal weight after population-standard-deviation scaling, with no clipping, log transform or imputation. Asset/market and outcome metadata do not enter the distance. LTV and distance-to-line are both retained as the brief’s feature vector requires, even though they are redundant in these equal-LLTV markets. Thus neighbors can cross assets/chains, and multiple nearby hours or positions from one market event can dominate. They are contextual examples, not independent votes or a calibrated liquidation probability. The default library is event-enriched by the original borrower selection.',
    'Feature units: LTV, distance-to-line, returns, realized volatility, utilization and annual continuous borrow rate are fractions; oracle gap is in percentage points; owner inactivity is hours; position size is collateral value in USD. Query JSON must supply every feature listed in `data/retrieval_scaler.json`, as finite numbers. Invalid/incomplete vectors are rejected, with no imputation. For an external vector without `--as-of`, the documented data cutoff is used. The frozen scaler cannot support a pre-2026 as-of query; that requires a separately fitted earlier scaler.',
    'From this folder, using the local environment:',
    '```sh\nscripts/.venv/bin/python3 -I scripts/retrieve.py --row-id '+str(examples['results'][0]['query']['query_row_id'])+' --k 3\nscripts/.venv/bin/python3 -I scripts/retrieve.py --queries-file data/retrieval_example_queries.json --output data/retrieval_examples_reproduced.json\n# For your own complete feature object:\nscripts/.venv/bin/python3 -I scripts/retrieve.py --features-file data/query.json --as-of 2026-10-26T00:00:00Z --k 5\n```',
    '### Five example queries and returned neighbors',
    'Exact queries and all returned summaries/flags are saved in `data/retrieval_example_queries.json` and `data/retrieval_examples.json`. These are demonstrations selected deterministically by observable features, not accuracy estimates. The stress query is near 85.5% LTV after a daily fall over 5%; the other four are near 78% and cover dust, both small Ethereum cohorts and fallback coverage. All five originate in 2026, retrieve only pre-2026 rows, and exclude the query position. Displayed feature values are rounded below; JSON retains full precision.']
    qtable=pd.DataFrame({'feature':sc['features']})
    for i,item in enumerate(examples['results'],1):qtable[f'Q{i}']=[f"{item['query']['features'][k]:.8g}" for k in sc['features']]
    text.append(md(qtable))
    for i,item in enumerate(examples['results'],1):
        q=item['query'];when=datetime.datetime.fromtimestamp(q['as_of'],datetime.timezone.utc).isoformat();text.append(f"**Q{i}: {q['name']}**, row {q['query_row_id']:,}, as of {when}; {item['eligible_candidates']:,} eligible candidates, k={q['k']}.")
        text.append(md(pd.DataFrame([dict(row=h['retrieval_id'],distance=f"{h['distance']:.6f}",summary=h['summary']) for h in item['neighbors']])))
    text+=['### Validation, timing and failures',
    f"All {v['rows_checked']:,} rows passed unique-key, screen, exclusion, missing-label and feature-completeness checks. {v['source_feature_samples']:,} sampled rows matched the original Step 2 features and labels; {v['direct_outcome_samples']:,} known windows matched direct event/owner-transaction queries. An independent centered-variance calculation reproduced the scaler. A full global distance sort verified all {nv['neighbors_checked']} returned neighbors for the five queries, and the public CLI reproduced their outputs. Validation records are `data/step3_validation.json` and `data/step3_neighbor_validation.json`.",
    'Timings below come from the corresponding saved status JSON and example output, in seconds. Successful invocation times can overlap; their sum is not elapsed wall time.',md(pd.DataFrame(timing)),
    f"Recorded wall span from starting the loss diagnostics to this report is {wall:.3f}s ({wall/60:.2f} minutes), including coding and validation gaps. The table build took {build['elapsed_s']:.3f}s; the five searches together took {examples['elapsed_s']:.3f}s, including disk reads. No external source was queried or re-downloaded in this task.",
    'Failures/limitations: no unresolved build or validation failure. An initial build was intentionally stopped to constrain disclosed outcomes to the matured 24-hour horizon, then rebuilt. The independent neighbor validator initially attempted to mutate a read-only pandas array; copying its mask fixed that check. A count export initially omitted a boolean/object positive-count column; the export now explicitly counts integers and reconciles to the table. Missing/censored windows, unresolved oracle phases, the small Ethereum cohorts and the inherited Aave exclusion remain explicit dataset limitations. The phase and heartbeat assumptions are not claims of new on-chain verification.',
    '### Reproduce this analysis and Step 3',
    'Run from this folder. No downloads, credentials, fitting of a risk classifier, or commits are required. Reporting scripts replace their own generated sections; run the loss report before the Step 3 report.',
    '```sh\nscripts/.venv/bin/python3 -I scripts/loss_analysis.py\nscripts/.venv/bin/python3 -I scripts/report_losses.py\nscripts/.venv/bin/python3 -I scripts/build_retrieval.py\nscripts/.venv/bin/python3 -I scripts/retrieval_examples.py\nscripts/.venv/bin/python3 -I scripts/validate_retrieval.py\nscripts/.venv/bin/python3 -I scripts/validate_neighbors.py\nscripts/.venv/bin/python3 -I scripts/report_step3.py\n```',
    '## Decisions before Step 4',
    '1. **Economic scope of the risk-model score:** retain every valid position as the primary population, or predeclare a minimum collateral/debt size. The $0.01 sale floor explains most ETH-type DEFAULT losses. Recommended: preserve the all-position result and separately report a declared economically meaningful size cohort; do not silently remove dust after seeing its holdout result. Choose that size cutoff before model fitting.',
    '2. **Oracle-source sensitivity:** fallback rows are accepted for retrieval. Confirm whether Step 4’s primary score also includes them with their flags, with a venue-feed-only sensitivity result, or whether that subset is the primary evaluation. Small-cohort and per-asset reporting should remain explicit; Aave and the 13 failed positions stay excluded.',
    '3. **Acceptance margin:** predeclare what “beats the screens” means beyond a positive position-bootstrap interval—for example, the minimum recall or lead-time gain at the same 5% alert-hour budget, plus the number/confidence level of bootstrap replicates. The brief requires position bootstrap, AUC, precision/recall, and lead time; it does not specify a practical minimum gain. Freeze the model recipe on training data before evaluating it.',
    'Step 4 must start from all eligible `features_hourly.parquet` rows, not this screen-filtered retrieval table; otherwise it would condition the evaluation on the baseline already firing. Apply the same reconstruction exclusions and missing-window masks. The 2026 holdout has now been inspected for these descriptive analyses, so any further choices informed by it must be disclosed. No Step 4 work has started. **Stopped after Step 3.**']
    s=(ROOT/'README.md').read_text().split('\n## Step 3 — retrieval completed')[0];s=s.replace('# Liquidation dataset — Steps 1 and 2','# Liquidation dataset — Steps 1, 2 and 3');s=s.replace('Step 2 is complete; stop here before Step 3.','Steps 2 and 3 are complete; stop before Step 4.')
    marker='\n## Decisions before Step 3' if '\n## Decisions before Step 3' in s else '\n## Step 3 decisions accepted'
    a=s.index(marker);b=s.index('\n## Why episodes are lost under the defaults',a)
    s=s[:a]+'\n## Step 3 decisions accepted\n\nThe founder retained the default corridor, included flagged Binance-fallback episodes, retained both small Ethereum cohorts with cohort flags, and excluded the 13 reconstruction failures. The requested loss analysis follows, then Step 3.\n'+s[b:]
    s=re.sub(r'Generated [^\n]+','Generated '+datetime.datetime.now(datetime.timezone.utc).isoformat()+'.',s,count=1)
    (ROOT/'README.md').write_text(s.rstrip()+'\n\n'+'\n\n'.join(text)+'\n')
    pd.DataFrame(timing).to_csv(D/'step3_source_times.csv',index=False)
    (D/'step3_report_status.json').write_text(json.dumps(dict(status='complete',started_at=started,finished_at=time.time(),elapsed_s=time.time()-started,wall_span_from_diagnostics_s=wall,extra_counts=extra),indent=2)+'\n');print(json.dumps(dict(status='complete',rows=build['screen_hours'],wall_span_s=wall,report_s=time.time()-started),indent=2))
if __name__=='__main__':main()
